import React from "react";
import { CheckCircle } from "lucide-react";

const StepNode = ({ title, active, children, up }) => {
  return (
    <div className="relative flex flex-col items-center">
      {/* children ABOVE */}
      {up && (
        <div className="absolute bottom-16 flex flex-col items-center text-[10px] text-neon-green space-y-1">
          {children}
        </div>
      )}

      {/* circle */}
      <div
        className={`w-12 h-12 rounded-full border-2 flex items-center justify-center z-10
        ${active ? "border-neon-green text-neon-green" : "border-gray-700 text-gray-600"}`}
      >
        {active ? <CheckCircle size={18} /> : ""}
      </div>

      <p className={`mt-3 text-[10px] font-bold ${active ? "text-white" : "text-gray-600"}`}>
        {title}
      </p>

      {/* children BELOW */}
      {!up && (
        <div className="mt-3 flex flex-col items-center text-[10px] text-neon-green space-y-1">
          {children}
        </div>
      )}
    </div>
  );
};

const CryptoTreeFlow = ({ currentStep }) => {
  return (
    <div className="relative w-full mt-10">
      {/* base line */}
      <div className="absolute top-6 left-0 w-full h-[2px] bg-gray-800"></div>

      <div
        className="absolute top-6 left-0 h-[2px] bg-neon-green transition-all duration-500"
        style={{ width: `${((currentStep - 1) / 4) * 100}%` }}
      />

      <div className="flex justify-between relative">
        {/* Phase 1 */}
        <StepNode title="Ephemeral Agreement" active={currentStep >= 1}>
          <>
            <span>Generate key</span>
            <span>Exchange public</span>
          </>
        </StepNode>

        {/* Phase 2 */}
        <StepNode title="Encapsulate Secret" active={currentStep >= 2} up>
          <>
            <span>Shared secret</span>
            <span>Create ciphertext</span>
          </>
        </StepNode>

        {/* Phase 3 */}
        <StepNode title="HKDF Derivation" active={currentStep >= 3}>
          <>
            <span>Mix salt</span>
            <span>Expand key</span>
          </>
        </StepNode>

        {/* Phase 4 */}
        <StepNode title="AES-GCM" active={currentStep >= 4} up>
          <>
            <span>Encrypt blocks</span>
            <span>Generate tag</span>
          </>
        </StepNode>

        {/* Phase 5 */}
        <StepNode title="Cloud Upload" active={currentStep >= 5}>
          <>
            <span>Pack blob</span>
            <span>Push storage</span>
          </>
        </StepNode>
      </div>
    </div>
  );
};

export default CryptoTreeFlow;
